INSERT INTO public.demo_responses(deliberation_id,ej_id,position,note)
SELECT d.id,e.id,x.position::public.vote_position,'DADOS FICTÍCIOS: ' || x.note
FROM examples x
JOIN public.deliberations d ON d.title=x.title AND d.is_demo=true
JOIN public.ejs e ON e.slug=x.slug
ON CONFLICT (deliberation_id,ej_id) DO NOTHING;
